// AUTO-GENERATED SCRIPT — reads vendor/openapi/keeper.yaml and emits src/api/constraints.gen.ts
// Run via: node scripts/gen-constraints.mjs  (called automatically by npm run gen:api)

import { readFileSync, writeFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';
import { parse } from 'yaml';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');

const specPath = resolve(root, 'vendor/openapi/keeper.yaml');
const outPath = resolve(root, 'src/api/constraints.gen.ts');

const spec = parse(readFileSync(specPath, 'utf8'));

function getNestedPath(obj, path) {
  return path.reduce((cur, key) => (cur != null ? cur[key] : undefined), obj);
}

// Декларативный список constraints: { key, schemaPath }
// schemaPath — массив ключей от корня spec до нужного поля
const WANTED = [
  {
    key: 'cadenceIntervalSecondsMin',
    schemaPath: ['components', 'schemas', 'CadenceCreateRequest', 'properties', 'interval_seconds', 'minimum'],
    crossCheckPath: ['components', 'schemas', 'CadencePatchRequest', 'properties', 'interval_seconds', 'minimum'],
  },
];

const entries = [];

for (const { key, schemaPath, crossCheckPath } of WANTED) {
  const value = getNestedPath(spec, schemaPath);
  if (value == null) {
    throw new Error(
      `gen-constraints: constraint '${key}' not found at path ${schemaPath.join('.')} in ${specPath}\n` +
      `Make sure vendor/openapi/keeper.yaml is up to date.`
    );
  }
  if (typeof value !== 'number') {
    throw new Error(`gen-constraints: constraint '${key}' is not a number (got ${typeof value}: ${value})`);
  }

  if (crossCheckPath) {
    const crossValue = getNestedPath(spec, crossCheckPath);
    if (crossValue == null) {
      console.warn(
        `gen-constraints WARNING: cross-check for '${key}': constraint missing at ${crossCheckPath.join('.')} ` +
        `(present in primary ${schemaPath.join('.')} = ${value}). ` +
        `Patch schema may have lost the minimum constraint — check vendor/openapi/keeper.yaml.`
      );
    } else if (crossValue !== value) {
      console.warn(
        `gen-constraints WARNING: cross-check mismatch for '${key}':\n` +
        `  ${schemaPath.join('.')} = ${value}\n` +
        `  ${crossCheckPath.join('.')} = ${crossValue}\n` +
        `Using value from primary path (${schemaPath.join('.')}).`
      );
    }
  }

  entries.push(`  ${key}: ${value},`);
}

const output = `// AUTO-GENERATED by scripts/gen-constraints.mjs from vendor/openapi/keeper.yaml — do not edit by hand.
// Re-run: npm run gen:api
export const CONSTRAINTS = {
${entries.join('\n')}
} as const;
`;

writeFileSync(outPath, output, 'utf8');
console.log(`gen-constraints: wrote ${outPath}`);
